#!/usr/bin/env bash
set -euo pipefail

APP_NAME="opportunity-fabric"
VERSION="0.1.0"
ARCHIVE_SHA256="9966e1a7d29a3d9a7cf844ca2cfa57bd018a4a34cb757b618ab7650cd6c22b3f"

if [ -n "${PREFIX:-}" ] && printf '%s' "$PREFIX" | grep -q 'com.termux'; then
  BIN_DIR="$PREFIX/bin"
else
  BIN_DIR="$HOME/.local/bin"
fi

APP_ROOT="$HOME/.local/share/$APP_NAME"
SRC_DIR="$APP_ROOT/current"
BACKUP_ROOT="$APP_ROOT/backups"
TMP_ROOT="${TMPDIR:-$HOME/.cache}"
STAMP="$(date +%Y%m%d-%H%M%S)"
TMP_DIR="$TMP_ROOT/${APP_NAME}-install-$STAMP"

cleanup() {
  rm -rf "$TMP_DIR" 2>/dev/null || true
}
trap cleanup EXIT

echo "==> Opportunity Fabric $VERSION — instalación automática"

# Dependencias mínimas. En Termux no hace pkg update innecesariamente.
if ! command -v python >/dev/null 2>&1; then
  if command -v pkg >/dev/null 2>&1; then
    echo "==> Instalando Python..."
    pkg install -y python
  else
    echo "ERROR: Python 3 no está instalado y este entorno no dispone de 'pkg'." >&2
    exit 1
  fi
fi

for cmd in tar gzip base64 sha256sum; do
  if ! command -v "$cmd" >/dev/null 2>&1; then
    if command -v pkg >/dev/null 2>&1; then
      echo "==> Instalando utilidades requeridas..."
      pkg install -y coreutils tar gzip
      break
    else
      echo "ERROR: falta '$cmd'." >&2
      exit 1
    fi
  fi
done

mkdir -p "$TMP_DIR" "$APP_ROOT" "$BACKUP_ROOT" "$BIN_DIR"

ARCHIVE="$TMP_DIR/$APP_NAME-$VERSION.tar.gz"
cat > "$TMP_DIR/payload.b64" <<'__OF_PAYLOAD__'

__OF_PAYLOAD__

base64 -d "$TMP_DIR/payload.b64" > "$ARCHIVE"
rm -f "$TMP_DIR/payload.b64"

ACTUAL_SHA="$(sha256sum "$ARCHIVE" | awk '{print $1}')"
if [ "$ACTUAL_SHA" != "$ARCHIVE_SHA256" ]; then
  echo "ERROR: checksum inválido. Esperado $ARCHIVE_SHA256, obtenido $ACTUAL_SHA" >&2
  exit 1
fi
echo "==> Payload verificado: SHA-256 OK"

tar -xzf "$ARCHIVE" -C "$TMP_DIR"
NEW_SRC="$TMP_DIR/opportunity-fabric-v0.1.0"

if [ -d "$SRC_DIR" ]; then
  echo "==> Respaldando instalación anterior..."
  mv "$SRC_DIR" "$BACKUP_ROOT/$STAMP"
fi

mkdir -p "$SRC_DIR"
cp -a "$NEW_SRC"/. "$SRC_DIR"/
find "$SRC_DIR" -type d -name '__pycache__' -prune -exec rm -rf {} + 2>/dev/null || true
find "$SRC_DIR" -type f \( -name '*.pyc' -o -name '*.pyo' \) -delete 2>/dev/null || true

cat > "$BIN_DIR/of" <<EOF
#!/usr/bin/env bash
set -euo pipefail
export PYTHONPATH="$SRC_DIR\${PYTHONPATH:+:\$PYTHONPATH}"
exec python -m opportunity_fabric "\$@"
EOF
chmod 700 "$BIN_DIR/of"

# Para Linux genérico, asegura ~/.local/bin en PATH. En Termux usamos $PREFIX/bin, ya presente.
if [ "$BIN_DIR" = "$HOME/.local/bin" ]; then
  case ":${PATH:-}:" in
    *":$BIN_DIR:"*) ;;
    *)
      PROFILE="$HOME/.profile"
      touch "$PROFILE"
      if ! grep -Fq 'export PATH="$HOME/.local/bin:$PATH"' "$PROFILE"; then
        printf '\nexport PATH="$HOME/.local/bin:$PATH"\n' >> "$PROFILE"
      fi
      export PATH="$BIN_DIR:$PATH"
      ;;
  esac
fi

echo "==> Ejecutando autopruebas..."
"$BIN_DIR/of" status >/dev/null
"$BIN_DIR/of" inventory >/dev/null
"$BIN_DIR/of" evaluate quantus >/dev/null
"$BIN_DIR/of" policies >/dev/null

echo
echo "OK — Opportunity Fabric $VERSION instalado y probado."
echo "Comando: of"
echo
"$BIN_DIR/of" status
